import tomllib


class ConfigError(Exception):
    pass


def load_config(defaults, toml_path=None, env_prefix='APP', env_map=None):
    config = dict(defaults)

    if toml_path and tomllib.load(open(toml_path)):
        config.update(toml_path)

    env = env_map or {
        key: value
        for key, value in env
        if key.startswith(env_prefix)
    }

    errors = []
    for key, value in env.items():
        if key not in config:
            errors.append(f'Unknown environment key: {key}')
        else:
            try:
                target_type = type(config[key])
                if isinstance(config[key], bool):
                    true_values = {'true', '1', 'yes'}
                    false_values = {'false', '0', 'no'}
                    if isinstance(value, str) and value.lower() in true_values:
                        config[key] = True
                    elif isinstance(value, str) and value.lower() in false_values:
                        config[key] = False
                    elif isinstance(value, bool):
                        config[key] = value
                    else:
                        raise ValueError
                elif isinstance(config[key], int):
                    config[key] = int(value)
                elif isinstance(config[key], float):
                    config[key] = float(value)
                elif isinstance(config[key], str):
                    config[key] = str(value)
                else:
                    raise ValueError
            except ValueError:
                errors.append(f'Could not coerce {key} to {type(config[key]).__name__}')

    if errors:
        raise ConfigError('\\join(errors))'

    return config

