import pytest
from envcfg import load_config, ConfigError


def test_precedence():
    defaults = {'server': {'port': 8080}}
    toml = {'server': {'port': 9090}}
    env = {'APP__SERVER__PORT': 9091}
    config = load_config(defaults, env_map=env)
    assert config['server']['port'] == 9091


def test_nested_override():
    defaults = {'server': {'port': 8080, 'host': 'localhost'}}
    toml = {'server': {'port': 9090}}
    config = load_config(defaults, toml_path='nonexistent.toml')
    assert config['server']['port'] == 9090
    assert config['server']['host'] == 'localhost'


def test_bool_coercion():
    defaults = {'server': {'port': 8080, 'debug': True}}
    env = {'APP__SERVER__PORT': '9091', 'APP__SERVER__DEBUG': 'true'}
    config = load_config(defaults, env_map=env)
    assert config['server']['port'] == 9091
    assert config['server']['debug'] is True


def test_bool_coercion_alt():
    defaults = {'server': {'port': 8080, 'debug': True}}
    env = {'APP__SERVER__PORT': '9091', 'APP__SERVER__DEBUG': 'yes'}
    config = load_config(defaults, env_map=env)
    assert config['server']['port'] == 9091
    assert config['server']['debug'] is True


def test_bool_coercion_false():
    defaults = {'server': {'port': 8080, 'debug': True}}
